<template><div class="page"><div class="toolbar"><el-input v-model="q.keyword" placeholder="任务名称或编号" @keyup.enter.native="load"/><el-button type="primary" @click="load">查询</el-button></div><el-table :data="rows"><el-table-column prop="taskNo" label="任务编号"/><el-table-column prop="taskName" label="任务名称"/><el-table-column prop="repositoryName" label="扫描源"/><el-table-column prop="scannedFiles" label="文件数" width="80"/><el-table-column prop="issueCount" label="问题数" width="80"/><el-table-column prop="highCount" label="高风险" width="80"/><el-table-column prop="mediumCount" label="中风险" width="80"/><el-table-column prop="createTime" label="完成时间" width="170"/><el-table-column label="操作" width="170"><template slot-scope="s"><el-button size="mini" @click="detail(s.row)">查看</el-button><el-button size="mini" @click="$router.push('/issues?resultId='+s.row.id)">结果明细</el-button></template></el-table-column></el-table><el-pagination class="pager" layout="total,prev,pager,next" :total="total" @current-change="p=>{q.pageNum=p;load()}"/><el-dialog title="扫描结果详情" :visible.sync="visible" width="720px"><template v-if="selected"><h3>{{selected.taskName}}</h3><div class="metrics"><div class="metric"><b>{{selected.scannedFiles}}</b>扫描文件</div><div class="metric"><b class="danger">{{selected.issueCount}}</b>问题总数</div><div class="metric"><b>{{selected.highCount}}</b>高风险</div><div class="metric"><b>{{selected.failedFiles}}</b>失败文件</div></div><div class="detail-grid"><div><label>任务编号</label>{{selected.taskNo}}</div><div><label>扫描源</label>{{selected.repositoryName}}</div><div><label>成功文件</label>{{selected.successFiles}}</div><div><label>完成时间</label>{{selected.createTime}}</div></div></template></el-dialog></div></template>
<script>import{resultApi}from'../api';export default{name:'ResultView',data(){return{q:{keyword:this.$route.query.taskNo||'',pageNum:1,pageSize:20},rows:[],total:0,visible:false,selected:null}},created(){this.load(true)},methods:{async load(autoOpen){const r=await resultApi.page(this.q);this.rows=r.list;this.total=r.total;if(autoOpen&&this.$route.query.taskNo){const row=this.rows.find(v=>v.taskNo===this.$route.query.taskNo);if(row)this.detail(row)}},async detail(r){this.selected=await resultApi.get(r.id);this.visible=true}}}</script>
